#!/usr/bin/env python3
import os
import subprocess
import glob

def test_word_file(word_file, env_vars):
    try:
        env = os.environ.copy()
        env.update(env_vars)
        result = subprocess.run(['bash', word_file], 
                              env=env,
                              capture_output=True,
                              text=True,
                              timeout=1)
        return result.stdout, result.stderr
    except Exception as e:
        return "", str(e)

def main():
    os.chdir('/home/ctfplayer/ctf_files/bdos/words')

    # Test environments
    env_combinations = [
        {'CONSTANTINE': 'flag', 'CLINIC': ''},
        {'CONSTANTINE': '', 'CLINIC': 'flag'},
        {'CONSTANTINE': 'flag', 'CLINIC': 'flag'},
    ]

    interesting_files = []

    for word_file in glob.glob('*'):
        print(f"\nTesting {word_file}:")
        for env_vars in env_combinations:
            stdout, stderr = test_word_file(word_file, env_vars)
            if 'flag' in stdout.lower() or 'key' in stdout.lower():
                print(f"Interesting output with {env_vars}:")
                print(f"stdout: {stdout}")
                interesting_files.append((word_file, env_vars, stdout))
            if stderr:
                print(f"stderr: {stderr}")

    print("\nInteresting files found:")
    for file, env, output in interesting_files:
        print(f"{file} with {env}: {output}")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
from pwn import *
import os
import time
import glob
import hashlib

def get_file_state(path):
    if not os.path.exists(path):
        return None
    with open(path, 'rb') as f:
        content = f.read()
        return {
            'size': len(content),
            'hash': hashlib.md5(content).hexdigest(),
            'content': content
        }

def monitor_directory(dir_path, timeout=5):
    # Get initial state
    files = {}
    for filepath in glob.glob(os.path.join(dir_path, '*')):
        if os.path.isfile(filepath):
            files[filepath] = get_file_state(filepath)

    # Run the challenge with timeout
    try:
        p = process(['./chal'], cwd=dir_path)
        time.sleep(timeout)
        p.close()
    except:
        pass

    # Check for changes
    changes = {}
    new_files = {}
    for filepath in glob.glob(os.path.join(dir_path, '*')):
        if os.path.isfile(filepath):
            new_state = get_file_state(filepath)
            if filepath not in files:
                new_files[filepath] = new_state
            elif files[filepath]['hash'] != new_state['hash']:
                changes[filepath] = {
                    'old': files[filepath],
                    'new': new_state
                }

    return changes, new_files

def analyze_content(content):
    # Try to decode content in different ways
    try:
        text = content.decode('utf-8')
        if 'flag{' in text:
            print(f"[+] Found possible flag pattern: {text}")
    except:
        pass

    # Look for flag-like patterns in hex
    hex_content = content.hex()
    if '666c6167' in hex_content:  # 'flag' in hex
        print(f"[+] Found 'flag' hex pattern")

def main():
    challenge_dir = '/home/ctfplayer/ctf_files/bdos'

    print("[*] Starting monitoring...")
    changes, new_files = monitor_directory(challenge_dir)

    print("\n[*] File changes detected:")
    for filepath, change in changes.items():
        print(f"\nFile: {filepath}")
        print(f"Old size: {change['old']['size']} bytes")
        print(f"New size: {change['new']['size']} bytes")
        analyze_content(change['new']['content'])

    print("\n[*] New files created:")
    for filepath, state in new_files.items():
        print(f"\nFile: {filepath}")
        print(f"Size: {state['size']} bytes")
        analyze_content(state['content'])

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
import os
import time
import hashlib
from subprocess import Popen, PIPE
import signal

def get_file_hash(filename):
    with open(filename, 'rb') as f:
        return hashlib.md5(f.read()).hexdigest()

def monitor_files(directory, timeout=5):
    # Track initial state
    files = {}
    for f in os.listdir(directory):
        if os.path.isfile(os.path.join(directory, f)):
            files[f] = get_file_hash(os.path.join(directory, f))

    # Start the challenge
    process = Popen(['./chal'], cwd=directory)

    # Monitor for changes
    start_time = time.time()
    changes = []

    try:
        while time.time() - start_time < timeout:
            time.sleep(0.1)
            for f in os.listdir(directory):
                if os.path.isfile(os.path.join(directory, f)):
                    current_hash = get_file_hash(os.path.join(directory, f))
                    if f in files and files[f] != current_hash:
                        changes.append(f)
                        files[f] = current_hash
    finally:
        process.kill()

    return changes

if __name__ == '__main__':
    print("Starting file monitoring...")
    changes = monitor_files('/home/ctfplayer/ctf_files/bdos')
    print("\nFiles changed during execution:")
    for file in set(changes):
        print(f"- {file}")
